    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 50 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  const issued = issueInvoice(r.value, []);
  const result = vatSummary([issued.value]);
  assert.equal(result.length, 3);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
  assert.equal(result[2].rate, 0);
});

test('vatSummary returns correct shape', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = vatSummary([issued.value]);
  const entry = result[0];
  assert.ok('rate' in entry);
  assert.ok('base' in entry);
  assert.ok('vat' in entry);
  assert.equal(Object.keys(entry).length, 3);
});

test('vatSummary with explicit discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = vatSummary([issued.value]);
  const subtotal = 2 * 8500;
  const discount = subtotal * 10 / 100;
  const expectedBase = subtotal - discount;
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary does not include vouchers', () => {
