test('vatSummary mixed statuses', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const r3 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-20',
    lines: [{ sku: 'PRINT-A4', qty: 50 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(r3.value, ['INV-2026-0002']);
  const totals3 = invoiceTotals(issued3.value);
  const partial3 = recordPayment(issued3.value, { amount: 5000, date: '2026-10-21' });
  const paid3 = recordPayment(partial3.value, { amount: totals3.total - 5000, date: '2026-10-22' });
  const result = vatSummary([issued1.value, issued2.value, paid3.value, r3.value]);
  assert.equal(result.length, 2);
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

