import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices finds single overdue invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].daysOverdue, 16);
  assert.equal(result[0].dueDate, '2026-09-21');
});

test('overdueInvoices includes due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const result = overdueInvoices([r.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const result = overdueInvoices([paid.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const withPayment = recordPayment(issued.value, { amount: 5000, date: '2026-10-08' });
  const result = overdueInvoices([withPayment.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].due, totals.total - 5000);
});

test('overdueInvoices excludes invoices with dueDate equal to asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-23',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes invoices with dueDate after asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET30',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices sorts by most overdue first', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = overdueInvoices([issued2.value, issued1.value], '2026-10-07');
  assert.equal(result.length, 2);
  assert.equal(result[0].daysOverdue, 22);
  assert.equal(result[1].daysOverdue, 8);
});

test('overdueInvoices includes multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = overdueInvoices([issued1.value, issued2.value], '2026-10-07');
  assert.equal(result.length, 2);
});

test('overdueInvoices filters by status from mixed array', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const totals2 = invoiceTotals(issued2.value);
  const paid2 = recordPayment(issued2.value, { amount: totals2.total, date: '2026-10-08' });
  const result = overdueInvoices([issued1.value, r2.value, paid2.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
});

