import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty array when no invoices', () => {
  const result = overdueInvoices([], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices returns empty array when no overdue invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices finds single overdue invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result.length, 1);
  assert.equal(result[0].number, 'INV-2026-0001');
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices calculates daysOverdue correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].daysOverdue, 16);
  assert.equal(result[0].dueDate, '2026-09-21');
});

test('overdueInvoices includes due amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const result = overdueInvoices([issued.value], '2026-10-07');
  assert.equal(result[0].due, totals.total);
});

test('overdueInvoices excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const result = overdueInvoices([r.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-09-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const result = overdueInvoices([paid.value], '2026-10-07');
  assert.deepEqual(result, []);
});

test('overdueInvoices includes issued invoices', () => {
