    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  const base1 = 8500 * (1 - 0.05);
  const base2 = 8500 * (1 - 0.025);
  const expectedBase = base1 + base2;
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary does not mutate input', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];
  vatSummary(invoices);
  assert.equal(invoices.length, 1);
  assert.equal(invoices[0].status, 'issued');
});

test('vatSummary with 100% discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 100 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = vatSummary([issued.value]);
  assert.equal(result[0].base, 0);
  assert.equal(result[0].vat, 0);
});

test('vatSummary aggregates from multiple invoices same rate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  const subtotal1 = 2 * 8500;
  const discount1 = subtotal1 * 5 / 100;
  const base1 = subtotal1 - discount1;
  const subtotal2 = 1 * 8500;
  const discount2 = subtotal2 * 0 / 100;
  const base2 = subtotal2 - discount2;
  const expectedBase = base1 + base2;
  assert.equal(result[0].base, expectedBase);
});

test('vatSummary rate is stored as number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const result = vatSummary([issued.value]);
  assert.equal(typeof result[0].rate, 'number');
});

